/**
 * The `/docs` page: the `@scalar/api-reference` standalone bundle from a
 * pinned CDN URL, pointed at `/openapi.json`.
 *
 * The HTML is the document `@scalar/hono-api-reference` rendered for this
 * configuration, byte for byte (its `_integration: "hono"` marker included),
 * written out here rather than generated by the Hono integration now that no
 * Hono route serves it. `__tests__/api-docs.test.ts` pins the bytes.
 */

/**
 * The bundle the page loads. Pinned: the default CDN URL is unversioned, so
 * the docs UI would otherwise track upstream releases, which is how the page
 * once rendered a v1 bundle against a v0.5 config shape. A bump changes the
 * config shape the bundle reads; check the page renders (client-library
 * picker included) before moving it.
 */
export const SCALAR_VERSION = "1.63.0";

/**
 * Scalar's configuration, in the order the integration wrote it. Snippets
 * are offered for the clients we can vouch for, curl the default: left
 * unfiltered, Scalar offers ~35 (Clojure, OCaml, ObjC, ...) that nobody here
 * has run against this API.
 */
const SCALAR_CONFIG = {
  _integration: "hono",
  url: "/openapi.json",
  defaultHttpClient: { targetKey: "shell", clientKey: "curl" },
  hiddenClients: {
    c: true,
    clojure: true,
    csharp: true,
    dart: true,
    http: true,
    java: true,
    kotlin: true,
    objc: true,
    ocaml: true,
    php: true,
    powershell: true,
    r: true,
    ruby: true,
    swift: true,
    // Keep one idiomatic client per remaining language.
    shell: ["httpie", "wget"],
    js: ["axios", "jquery", "ofetch", "xhr"],
    node: ["axios", "ofetch", "undici"],
    python: ["python3"],
  },
  theme: "default",
} as const;

const PAGE_TITLE = "Infrawrench API";

/** The configuration as the inline script's object literal, indented into the page. */
const configLiteral = JSON.stringify(SCALAR_CONFIG, null, 2)
  .split("\n")
  .map((line, index) => (index === 0 ? line : `      ${line}`))
  .join("\n");

export const REFERENCE_PAGE = `<!doctype html>
<html>
  <head>
    <title>${PAGE_TITLE}</title>
    <meta charset="utf-8" />
    <meta
      name="viewport"
      content="width=device-width, initial-scale=1" />
  </head>
  <body>
    <div id="app"></div>
    <!-- Load the Script -->
    <script src="https://cdn.jsdelivr.net/npm/@scalar/api-reference@${SCALAR_VERSION}"></script>

    <!-- Initialize the Scalar API Reference -->
    <script type="text/javascript">
      Scalar.createApiReference('#app', ${configLiteral})
    </script>
  </body>
</html>`;
